16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
20	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
21	
22	import jakarta.persistence.*;
23	import jakarta.validation.constraints.NotEmpty;
24	import jakarta.validation.constraints.Pattern;
25	
26	import java.time.LocalDate;
27	import java.util.*;
28	
29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "postcode")
57	    private String postcode;
58	
59	    @Column(name = "registration_date")
60	    private LocalDate registrationDate;
61	
62	    @Column(name = "birth_date")
63	    private LocalDate birthDate;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "namesake_count")
72	    private Integer namesakeCount;
73	
74	    @Column(name = "membership_number")
75	    private String membershipNumber;
76	
77	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
78	    private Set<Pet> pets;
79	
80	    /**
81	     * Default the registration date to the server's current date when none was
82	     * supplied, then roll the effective date forward onto a business day so a
83	     * weekend registration date always lands on the following Monday. Runs only
84	     * on insert.
85	     */
86	    @PrePersist
87	    private void defaultRegistrationDate() {
88	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
89	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
90	    }
91	
92	    public String getAddress() {
93	        return this.address;
94	    }
95	
96	    public void setAddress(String address) {
97	        this.address = address;
98	    }
99	
100	    public String getCity() {
101	        return this.city;
102	    }
103	
104	    public void setCity(String city) {
105	        this.city = city;
106	    }
107	
108	    public String getTelephone() {
109	        return this.telephone;
110	    }
111	
112	    public void setTelephone(String telephone) {
113	        this.telephone = telephone;
114	    }
115	
116	    public String getEmail() {
117	        return this.email;
118	    }
119	
120	    public void setEmail(String email) {
121	        this.email = email;
122	    }
123	
124	    public String getPostcode() {
125	        return this.postcode;
126	    }
127	
128	    public void setPostcode(String postcode) {
129	        this.postcode = postcode;
130	    }
131	
132	    public LocalDate getRegistrationDate() {
133	        return this.registrationDate;
134	    }
135	
136	    public void setRegistrationDate(LocalDate registrationDate) {
137	        this.registrationDate = registrationDate;
138	    }
139	
140	    public LocalDate getBirthDate() {
141	        return this.birthDate;
142	    }
143	
144	    public void setBirthDate(LocalDate birthDate) {
145	        this.birthDate = birthDate;
146	    }
147	
148	    public String getCustomerCode() {
149	        return this.customerCode;
150	    }
151	
152	    public void setCustomerCode(String customerCode) {
153	        this.customerCode = customerCode;
154	    }
155	
156	    public String getHouseholdId() {
157	        return this.householdId;
158	    }
159	
160	    public void setHouseholdId(String householdId) {
161	        this.householdId = householdId;
162	    }
163	
164	    public Integer getNamesakeCount() {
165	        return this.namesakeCount;
166	    }
167	
168	    public void setNamesakeCount(Integer namesakeCount) {
169	        this.namesakeCount = namesakeCount;
170	    }
171	
172	    public String getMembershipNumber() {
173	        return this.membershipNumber;
174	    }
175	
176	    public void setMembershipNumber(String membershipNumber) {
177	        this.membershipNumber = membershipNumber;
178	    }
179	
180	    /**
181	     * Return this owner's name formatted as {@code LastName, FirstName}.
182	     */
183	    @Transient
184	    public String getDisplayName() {
185	        return this.getLastName() + ", " + this.getFirstName();
186	    }
187	
188	    /**
189	     * Return this owner's identity key: the single value all duplicate detection is based on,
190	     * formed as {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or
191	     * household id contributes an empty segment). Two owners are duplicates only when their whole
192	     * identity keys are equal, so members of the same household with different telephones — and thus
193	     * different keys — are distinct. The telephone and email are expected to already be in their
194	     * normalized storage form.
195	     */
196	    @Transient
197	    public String getIdentityKey() {
198	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
199	    }
200	
201	    private static String orEmpty(String value) {
202	        return value == null ? "" : value;
203	    }
204	
205	    /**
206	     * Return this owner's locality: the REGION segment of the owner's
207	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
208	     * When no customer code has been assigned yet the region is resolved directly from the
209	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
210	     */
211	    @Transient
212	    public String getLocality() {
213	        if (this.customerCode != null && !this.customerCode.isBlank()) {
214	            return CustomerCodeGenerator.regionOf(this.customerCode);
215	        }
216	        return RegionResolver.regionFor(this.postcode, this.city);
217	    }
218	
219	    /**
220	     * Return this owner's membership level: starting at 1, plus 1 when the owner
221	     * has an email, plus 1 when the owner is uniquely named (a
222	     * {@link #getNamesakeCount() namesakeCount} of 0), capped at 3. Level 4 is
223	     * reserved for tenure.
224	     */
225	    @Transient
226	    public int getMembershipLevel() {
227	        int level = 1;
228	        boolean hasEmail = this.email != null && !this.email.isEmpty();
229	        if (hasEmail) {
230	            level++;
231	        }
232	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
233	        if (uniquelyNamed) {
234	            level++;
235	        }
236	        return Math.min(level, 3);
237	    }
238	
239	    /**
240	     * Return this owner's check digit: the single Luhn check digit computed over the
241	     * digits of the {@link #getCustomerCode() customer code}.
242	     */
243	    @Transient
244	    public int getCheckDigit() {
245	        return LuhnCheckDigit.of(this.customerCode);
246	    }
247	
248	    /**
249	     * Return this owner's preferred contact channel: {@code EMAIL} when an
250	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
251	     */
252	    @Transient
253	    public String getContactPreference() {
254	        boolean hasEmail = this.email != null && !this.email.isEmpty();
255	        return hasEmail ? "EMAIL" : "PHONE";
256	    }
257	
258	    /**
259	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
260	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
261	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
262	     */
263	    @Transient
264	    public String getAgeBand() {
265	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
266	        return ageBand == null ? null : ageBand.name();
267	    }
268	
269	    protected Set<Pet> getPetsInternal() {
270	        if (this.pets == null) {
271	            this.pets = new HashSet<>();
272	        }
273	        return this.pets;
274	    }
275	
276	    protected void setPetsInternal(Set<Pet> pets) {
277	        this.pets = pets;
278	    }
279	
280	    public List<Pet> getPets() {
281	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
282	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
283	        return Collections.unmodifiableList(sortedPets);
284	    }
285	
286	    public void setPets(List<Pet> pets) {
287	        this.pets = new HashSet<>(pets);
288	    }
289	
290	    public void addPet(Pet pet) {
291	        getPetsInternal().add(pet);
292	        pet.setOwner(this);
293	    }
294	
295	    /**
296	     * Return the Pet with the given name, or null if none found for this Owner.
297	     *
298	     * @param name to test
299	     * @return true if pet name is already in use
300	     */
301	    public Pet getPet(String name) {
302	        return getPet(name, false);
303	    }
304	
305	    /**
306	     * Return the Pet with the given name, or null if none found for this Owner.
307	     *
308	     * @param name to test
309	     * @return true if pet name is already in use
310	     */
311	    public Pet getPet(String name, boolean ignoreNew) {
312	        name = name.toLowerCase();
313	        for (Pet pet : getPetsInternal()) {
314	            if (!ignoreNew || !pet.isNew()) {
315	                String compName = pet.getName();
316	                compName = compName.toLowerCase();
317	                if (compName.equals(name)) {
318	                    return pet;
319	                }
320	            }
321	        }
322	        return null;
323	    }
324	
325	    public Pet getPet(Integer petId) {
326	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
327	    }
328	
329	    @Override
330	    public String toString() {
331	        return new ToStringCreator(this)
332	
333	            .append("id", this.getId())
334	            .append("new", this.isNew())
335	            .append("lastName", this.getLastName())
336	            .append("firstName", this.getFirstName())
337	            .append("address", this.address)
338	            .append("city", this.city)
339	            .append("telephone", this.telephone)
340	            .append("email", this.email)
341	            .toString();
342	    }
343	}
