16	package org.springframework.samples.petclinic.model;
17	
18	import jakarta.persistence.Column;
19	import jakarta.persistence.MappedSuperclass;
20	import jakarta.persistence.Transient;
21	
22	import jakarta.validation.constraints.NotEmpty;
23	
24	/**
25	 * Simple JavaBean domain object representing an person.
26	 *
27	 * @author Ken Krebs
28	 */
29	@MappedSuperclass
30	public class Person extends BaseEntity {
31	
32	    @Column(name = "first_name")
33	    @NotEmpty
34	    protected String firstName;
35	
36	    @Column(name = "last_name")
37	    @NotEmpty
38	    protected String lastName;
39	
40	    public String getFirstName() {
41	        return this.firstName;
42	    }
43	
44	    public void setFirstName(String firstName) {
45	        this.firstName = firstName;
46	    }
47	
48	    public String getLastName() {
49	        return this.lastName;
50	    }
51	
52	    public void setLastName(String lastName) {
53	        this.lastName = lastName;
54	    }
55	
56	    /**
57	     * Return this person's initials: the upper-cased first letters of the first
58	     * and last name, dot-separated with a trailing dot (e.g. {@code J.S.}).
59	     */
60	    @Transient
61	    public String getInitials() {
62	        return initial(this.firstName) + initial(this.lastName);
63	    }
64	
65	    private static String initial(String name) {
66	        return Character.toUpperCase(name.charAt(0)) + ".";
67	    }
68	
69	}
