30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.model.BusinessDayAdjuster;
33	import org.springframework.samples.petclinic.model.RegionResolver;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.audit.OwnerAuditLogger;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.CityOwnerCapacityValidator;
44	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
45	import org.springframework.samples.petclinic.rest.validation.DailyRegistrationCapacityValidator;
46	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
47	import org.springframework.samples.petclinic.rest.validation.MembershipNumberGenerator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
49	import org.springframework.samples.petclinic.rest.validation.NamesakeCounter;
50	import org.springframework.samples.petclinic.rest.validation.OwnerHouseholdRegistrar;
51	import org.springframework.samples.petclinic.rest.validation.OwnerIdentityUniquenessValidator;
52	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
53	import org.springframework.samples.petclinic.rest.validation.RegistrationDateValidator;
54	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
55	import org.springframework.samples.petclinic.service.ClinicService;
56	import org.springframework.security.access.prepost.PreAuthorize;
57	import org.springframework.web.bind.annotation.CrossOrigin;
58	import org.springframework.web.bind.annotation.RequestMapping;
59	import org.springframework.web.bind.annotation.RestController;
60	import org.springframework.web.util.UriComponentsBuilder;
61	
62	import jakarta.transaction.Transactional;
63	
64	/**
65	 * @author Vitaliy Fedoriv
66	 */
67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    private final OwnerIdentityUniquenessValidator identityUniquenessValidator;
82	
83	    private final OwnerHouseholdRegistrar householdRegistrar;
84	
85	    private final NamesakeCounter namesakeCounter;
86	
87	    private final CityOwnerCapacityValidator cityOwnerCapacityValidator;
88	
89	    private final DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator;
90	
91	    private final OwnerAuditLogger ownerAuditLogger;
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 OwnerIdentityUniquenessValidator identityUniquenessValidator,
98	                                 OwnerHouseholdRegistrar householdRegistrar,
99	                                 NamesakeCounter namesakeCounter,
100	                                 CityOwnerCapacityValidator cityOwnerCapacityValidator,
101	                                 DailyRegistrationCapacityValidator dailyRegistrationCapacityValidator,
102	                                 OwnerAuditLogger ownerAuditLogger) {
103	        this.clinicService = clinicService;
104	        this.ownerMapper = ownerMapper;
105	        this.petMapper = petMapper;
106	        this.visitMapper = visitMapper;
107	        this.identityUniquenessValidator = identityUniquenessValidator;
108	        this.householdRegistrar = householdRegistrar;
109	        this.namesakeCounter = namesakeCounter;
110	        this.cityOwnerCapacityValidator = cityOwnerCapacityValidator;
111	        this.dailyRegistrationCapacityValidator = dailyRegistrationCapacityValidator;
112	        this.ownerAuditLogger = ownerAuditLogger;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
141	    @Override
142	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
143	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
144	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
148	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
149	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
150	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
151	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
152	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
153	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
154	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
155	            this.householdRegistrar.assignHousehold(owner);
156	        }
157	        this.identityUniquenessValidator.validateUnique(owner);
158	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
159	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
160	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
161	        owner.setCustomerCode(CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName()));
162	        this.clinicService.saveOwner(owner);
163	        owner.setMembershipNumber(MembershipNumberGenerator.generate(owner.getCustomerCode(), owner.getRegistrationDate()));
164	        this.ownerAuditLogger.logCreated(owner);
165	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
166	        headers.setLocation(UriComponentsBuilder.newInstance()
167	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
168	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
169	    }
170	
171	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
172	    @Override
173	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
174	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
175	        if (currentOwner == null) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        currentOwner.setAddress(ownerFieldsDto.getAddress());
179	        currentOwner.setCity(ownerFieldsDto.getCity());
180	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
181	        currentOwner.setLastName(ownerFieldsDto.getLastName());
182	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
183	        this.clinicService.saveOwner(currentOwner);
