20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Enforces that no two owners share an {@link Owner#getIdentityKey() identity key} — the single
25	 * derived value ({@code normalizedTelephone + '|' + email + '|' + householdId}) that all duplicate
26	 * detection is based on. Only an exact whole-key match is a duplicate, so owners that differ in any
27	 * one component (for example two members of the same household with different telephones) are
28	 * allowed.
29	 */
30	@Component
31	public class OwnerIdentityUniquenessValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    public OwnerIdentityUniquenessValidator(ClinicService clinicService) {
36	        this.clinicService = clinicService;
37	    }
38	
39	    /**
40	     * Rejects an owner whose identity key equals that of an existing owner. The owner's telephone,
41	     * email and household id must already be in their final form when this runs.
42	     *
43	     * @param owner the owner being created
44	     * @throws DuplicateOwnerIdentityException if another owner already has this identity key
45	     */
46	    public void validateUnique(Owner owner) {
47	        String identityKey = owner.getIdentityKey();
48	        boolean duplicate = this.clinicService.findAllOwners().stream()
49	            .anyMatch(existing -> existing.getIdentityKey().equals(identityKey));
50	        if (duplicate) {
51	            throw new DuplicateOwnerIdentityException(identityKey);
52	        }
53	    }
54	}
